def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def find_max_r():
    max_r = -1
    solutions = []

    # We want to maximize r, so we iterate through p starting from the smallest odd prime (p=3).
    # Since p < q < r and p+r=800, p must be small enough so r > q > p.
    # Since q > p, we need 800 - p > p + 1, so 799 > 2p, p < 399.5.

    p_candidates = [p for p in range(3, 400, 2) if is_prime(p)]

    for p in p_candidates:
        r = 800 - p

        if not is_prime(r):
            continue

        # Since p < q < r, we need to check primes q in range(p + 1, r)
        q_candidates = [q for q in range(p + 1, r) if is_prime(q)]

        for q in q_candidates:

            # Condition 1: r+p-q must be prime (800 - q must be prime)
            P1 = 800 - q
            if not is_prime(P1):
                continue

            # Condition 2: p+q+r must be prime (800 + q must be prime)
            P2 = 800 + q
            if not is_prime(P2):
                continue

            # Condition 3: p+q-r must be prime
            S1 = p + q - r
            if not is_prime(S1):
                continue

            # Condition 4: q+r-p must be prime
            S2 = q + r - p
            if not is_prime(S2):
                continue

            # All conditions met. Record the solution (p, q, r).
            solutions.append(r)

        # Optimization: Since we iterate p increasingly, r=800-p is decreasing.
        # We can stop searching if we have found at least one solution, assuming the problem implies a unique maximum r, 
        # but to be safe, we'll just track the max and rely on the loop structure.

    if solutions:
        return max(solutions)
    else:
        return "No solutions found"

